use std::env;
use std::fs;
use std::process;

#[derive(Clone)]
struct Field {
    key: String,
    value: String,
}

struct Section {
    name: String,
    inherits: Option<String>,
    fields: Vec<Field>,
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn parse_quoted(raw: &str, line_number: usize) -> String {
    let value = raw.trim();
    if !value.starts_with('"') {
        fail(format!("expected quoted value on line {}", line_number));
    }

    let mut parsed = String::new();
    let mut characters = value[1..].chars();
    loop {
        match characters.next() {
            Some('"') => {
                if characters.any(|character| !character.is_whitespace()) {
                    fail(format!("trailing data on line {}", line_number));
                }
                return parsed;
            }
            Some('\\') => match characters.next() {
                Some('"') => parsed.push('"'),
                Some('\\') => parsed.push('\\'),
                Some('n') => parsed.push('\n'),
                Some('r') => parsed.push('\r'),
                Some('t') => parsed.push('\t'),
                Some(escaped) => fail(format!(
                    "unsupported escape {:?} on line {}",
                    escaped, line_number
                )),
                None => fail(format!("unterminated escape on line {}", line_number)),
            },
            Some(character) => parsed.push(character),
            None => fail(format!("unterminated quoted value on line {}", line_number)),
        }
    }
}

fn main() {
    let mut arguments = env::args();
    arguments.next();
    let path = match arguments.next() {
        Some(path) => path,
        None => fail("missing input path"),
    };
    if arguments.next().is_some() {
        fail("unexpected extra argument");
    }

    let input = match fs::read_to_string(&path) {
        Ok(input) => input,
        Err(error) => fail(format!("cannot read {}: {}", path, error)),
    };

    let mut sections: Vec<Section> = Vec::new();
    let mut current: Option<usize> = None;

    for (index, line) in input.lines().enumerate() {
        let line_number = index + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if trimmed.starts_with('[') {
            if !trimmed.ends_with(']') || trimmed.len() < 3 {
                fail(format!("malformed section header on line {}", line_number));
            }
            let name = trimmed[1..trimmed.len() - 1].trim();
            if name.is_empty() {
                fail(format!("empty section name on line {}", line_number));
            }
            if sections.iter().any(|section| section.name == name) {
                fail(format!("duplicate section {:?}", name));
            }
            sections.push(Section {
                name: name.to_owned(),
                inherits: None,
                fields: Vec::new(),
            });
            current = Some(sections.len() - 1);
            continue;
        }

        let section_index = current
            .unwrap_or_else(|| fail(format!("field before section on line {}", line_number)));
        let (key, raw_value) = match trimmed.split_once('=') {
            Some(parts) => parts,
            None => fail(format!("malformed field on line {}", line_number)),
        };
        let key = key.trim();
        if key.is_empty() {
            fail(format!("empty field name on line {}", line_number));
        }
        let value = parse_quoted(raw_value, line_number);
        let section = &mut sections[section_index];

        if key == "inherits" {
            if section.inherits.is_some() {
                fail(format!(
                    "duplicate field {:?} in section {:?}",
                    key, section.name
                ));
            }
            section.inherits = Some(value);
        } else {
            if section.fields.iter().any(|field| field.key == key) {
                fail(format!(
                    "duplicate field {:?} in section {:?}",
                    key, section.name
                ));
            }
            section.fields.push(Field {
                key: key.to_owned(),
                value,
            });
        }
    }

    let mut output = String::new();
    for section_index in 0..sections.len() {
        let section_name = sections[section_index].name.clone();
        let parent_name = sections[section_index].inherits.clone();
        let mut resolved = match parent_name {
            Some(parent_name) => {
                let parent_index = sections
                    .iter()
                    .position(|section| section.name == parent_name)
                    .unwrap_or_else(|| {
                        fail(format!(
                            "unknown inherited section {:?} for {:?}",
                            parent_name, section_name
                        ))
                    });
                if sections[parent_index].inherits.is_some() {
                    fail(format!(
                        "section {:?} inherits through {:?}",
                        section_name, parent_name
                    ));
                }
                sections[parent_index].fields.clone()
            }
            None => Vec::new(),
        };

        for field in &sections[section_index].fields {
            if let Some(existing) = resolved.iter_mut().find(|item| item.key == field.key) {
                existing.value = field.value.clone();
            } else {
                resolved.push(field.clone());
            }
        }

        for field in resolved {
            output.push_str(&section_name);
            output.push('.');
            output.push_str(&field.key);
            output.push('=');
            output.push_str(&field.value);
            output.push('\n');
        }
    }

    print!("{}", output);
}
